  const details = payload.result?.details;
  const markdownDetails = payloadType(markdown.payload).result?.details;
  const controlDetails = payloadType(control.payload).result?.details;
  const text = details?.text ?? "";
  const markdownText = markdownDetails?.text ?? "";
  const controlText = controlDetails?.text ?? "";
